#include "helpers.hpp"
int main(){const std::string base="/REQUIRED_EXTERNAL_INPUT/Corsairs/.local-archives/metal-renderer-evidence/world-cut-surface/reopen-production-radius220/";struct Role{const char*name;std::set<int>terrain;};
for(const auto&r:std::vector<Role>{{"Antigua-Antigua.bin",{0,1,2,3}},{"Cumana-Cumana.bin",{0,1,2,3,4}},{"Antigua-antigua_fort1.bin",{}},{"Cumana-Cumana_Fort1.bin",{}}}){auto source=load((base+r.name).c_str());const auto&t=source.begin()->second[source.begin()->second.size()/2];auto pos=(t[0].position+t[1].position+t[2].position)*(1.f/3);auto n=storm_ship_hull::normalized(storm_ship_hull::cross(t[1].position-t[0].position,t[2].position-t[0].position));for(unsigned count:{1,8}){std::vector<Cut>cuts;for(unsigned k=0;k<count;k++){Cut c;c.kind=Cut::Beam;c.field=k+1;storm_hull_damage::BeamSample b;auto start=pos+n*.001f+n*(-.3f*k);b.start={start.x,start.y,start.z};b.direction={-n.x,-n.y,-n.z};b.depth=.3f;c.beams={b};cuts.push_back(c);}Mesh out,outer,caps;std::vector<CapPatch>patches;cut_cost::totals.clear();auto start=std::chrono::steady_clock::now();bool ok=reconstructWorld(source,r.terrain,cuts,out,&outer,&caps,&patches);auto total=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<r.name<<" tris="<<triangleCount(source)<<" cuts="<<count<<" ok="<<ok<<" total="<<total<<" out="<<triangleCount(out);for(auto&x:cut_cost::totals)std::cout<<" "<<x.first<<"="<<x.second;std::cout<<std::endl;}}}
